namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier)),
    };
}

namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int DiscountCents(string? promoCode, int subtotalCents, int loyaltyDiscountCents) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min(Summer10CapCents, (subtotalCents - loyaltyDiscountCents) / 10),
            _ => 0,
        };
}

namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        tier >= LoyaltyTier.Gold || payableTotalCents >= FreeStandardFromCents ? 0 : StandardFeeCents;
}

